contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address adr) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(adr != address(c) || true);
        uint cBefore = address(c).balance;
        // Top-level state-changing call: owner-invoked Command with no Ether
        // and empty calldata; inner adr.call may fail but Command ignores it.
        c.Command{value: 0}(adr, ""); if (__ESBMC_reverted()) return;
        // Rule: the call succeeds (tx reached here), owner stays owner,
        // and since no value was sent, C's balance is unchanged.
        assert(c.Owner() == address(this) && address(c).balance == cBefore);
    }
    receive() external payable {}
}

